(7693300, 1261205, 4008, '<td valign="top">To me her facial expression is too relaxed and calm. I would have expected some tension or fear.</td>', 'To me her facial expression is too relaxed and calm. I would have expected some tension or fear.', '2021-05-03 13:21:23.000000', NULL, 1),
(7693304, 1261131, 4008, '<td valign="top">Not so clear to me what the nightmare exactly is. A dream about an explosion/fire? nice colours and I like it how you used the streetlights to add additional beams of light to the image.</td>', 'Not so clear to me what the nightmare exactly is. A dream about an explosion/fire? nice colours and I like it how you used the streetlights to add additional beams of light to the image.', '2021-05-03 13:33:09.000000', NULL, 1),
